                    if (!visible) {
                        throw new Error(`Visibility assertion failed: ${step.selector} not visible`);
                    }
                    break;
                }

                case 'hover':
                    await page.hover(step.selector, { timeout: 5000 });
                    break;

                case 'select':
                    await page.selectOption(step.selector, step.value, { timeout: 5000 });
                    break;

                case 'press':
                    await page.press(step.selector, step.key, { timeout: 5000 });
                    break;

                case 'scroll':
                    await page.evaluate((sel) => {
                        const el = document.querySelector(sel);
                        if (el) el.scrollIntoView({ behavior: 'smooth', block: 'center' });
                    }, step.selector);
                    break;

                default:
                    console.warn(`Unknown action type: ${step.action}`);
                    continue;
            }

            interactions.push({
                type:      step.action,
                target:    step.selector || step.name,
                timestamp: new Date().toISOString(),
                success:   true
            });

            // Brief pause between steps for UI settling
            await page.waitForTimeout(step.delay || 300);

        } catch (error) {
            console.error(`Step "${step.action}" on "${step.selector}" failed: ${error.message}`);

            interactions.push({
                type:      step.action,
                target:    step.selector || step.name || 'unknown',
                timestamp: new Date().toISOString(),
                success:   false,
                error:     error.message
            });

            // If step is marked as critical, abort entire plan
            if (step.critical) {
                return { success: false, interactions, abortReason: error.message };
            }
        }
    }

    const successCount = interactions.filter(i => i.success).length;
    const successRate  = interactions.length > 0
        ? successCount / interactions.length
        : 0;

    return {
        success:      successRate >= (plan.successThreshold ?? 0.8),
        interactions,
        successRate
    };
