// ═══════════════════════════════════════════════════════════════════════
// BROWSER WORKER - HTTP Server Accepting Task Requests
// ═══════════════════════════════════════════════════════════════════════
// File: services/testing_agent/src/browser_worker.js

import http        from 'http';
import { executeTest, postResult } from './index.js';

const PORT    = parseInt(process.env.PORT ?? '4000', 10);
const HOST    = process.env.HOST ?? '0.0.0.0';

// In-flight task map (taskId → Promise) for deduplication
const inFlight = new Map();

const server = http.createServer(async (req, res) => {
    // ─── Health check ─────────────────────────────────────────
    if (req.method === 'GET' && req.url === '/health') {
        res.writeHead(200, { 'Content-Type': 'application/json' });
        res.end(JSON.stringify({
            status:    'healthy',
            inFlight:  inFlight.size,
            timestamp: new Date().toISOString()
        }));
        return;
    }

    // ─── Metrics endpoint ─────────────────────────────────────
    if (req.method === 'GET' && req.url === '/metrics') {
        res.writeHead(200, { 'Content-Type': 'text/plain' });
        res.end([
            `# HELP testing_agent_in_flight_tasks Currently executing browser tasks`,
            `# TYPE testing_agent_in_flight_tasks gauge`,
            `testing_agent_in_flight_tasks ${inFlight.size}`,
        ].join('\n'));
        return;
    }

    // ─── Task submission ──────────────────────────────────────
    if (req.method === 'POST' && req.url === '/run') {
        let body = '';
        req.on('data', chunk => (body += chunk));
        req.on('end', async () => {
            let task;
            try {
                task = JSON.parse(body);
            } catch {
                res.writeHead(400, { 'Content-Type': 'application/json' });
                res.end(JSON.stringify({ error: 'Invalid JSON body' }));
                return;
            }

            // Validate required fields
            if (!task.taskId || !task.previewUrl) {
                res.writeHead(422, { 'Content-Type': 'application/json' });
                res.end(JSON.stringify({ error: 'Missing required fields: taskId, previewUrl' }));
                return;
            }

            // Deduplication guard
            if (inFlight.has(task.taskId)) {
                res.writeHead(409, { 'Content-Type': 'application/json' });
                res.end(JSON.stringify({ error: 'Task already in flight', taskId: task.taskId }));
                return;
            }

            // Acknowledge immediately, run async
            res.writeHead(202, { 'Content-Type': 'application/json' });
            res.end(JSON.stringify({ status: 'accepted', taskId: task.taskId }));

            // Execute and report
            const promise = (async () => {
                try {
                    const result = await executeTest(task);
                    await postResult(result);
                } catch (err) {
                    console.error(`[${task.taskId}] Unhandled error:`, err);
                    await postResult({
                        taskId:  task.taskId,
                        success: false,
                        error:   { message: err.message, stack: err.stack }
                    });
                } finally {
                    inFlight.delete(task.taskId);
                }
            })();

            inFlight.set(task.taskId, promise);
        });
        return;
    }

    // ─── 404 fallback ─────────────────────────────────────────
    res.writeHead(404, { 'Content-Type': 'application/json' });
    res.end(JSON.stringify({ error: 'Not found' }));
});

server.listen(PORT, HOST, () => {
    console.log(`Testing Agent HTTP server listening on ${HOST}:${PORT}`);
});

process.on('SIGTERM', () => {
    console.log('SIGTERM received – draining in-flight tasks...');
    server.close(async () => {
        await Promise.allSettled([...inFlight.values()]);
        console.log('All in-flight tasks drained, exiting.');
        process.exit(0);
    });
});
