-- ═══════════════════════════════════════════════════════════════════════
-- MIGRATION 001 – Create Sessions Table
-- ═══════════════════════════════════════════════════════════════════════
-- File: db/migrations/001_create_sessions.sql

BEGIN;

-- Extension for UUID generation
CREATE EXTENSION IF NOT EXISTS "uuid-ossp";
CREATE EXTENSION IF NOT EXISTS "pg_trgm";   -- For text search on metadata

-- ─── Migration tracking table ────────────────────────────
CREATE TABLE IF NOT EXISTS schema_migrations (
    version    INT PRIMARY KEY,
    applied_at TIMESTAMPTZ NOT NULL DEFAULT now()
);

-- ─── Sessions table ───────────────────────────────────────
CREATE TABLE sessions (
    id           UUID        PRIMARY KEY DEFAULT uuid_generate_v4(),
    user_id      UUID        NOT NULL,
    workflow_id  TEXT        UNIQUE,           -- Temporal workflow run ID
    started_at   TIMESTAMPTZ NOT NULL DEFAULT now(),
    finished_at  TIMESTAMPTZ,
    status       TEXT        NOT NULL
                             CHECK (status IN ('running','completed','failed','cancelled','timeout')),
    user_prompt  TEXT        NOT NULL,
    metadata     JSONB       NOT NULL DEFAULT '{}',
    policy_score DOUBLE PRECISION,             -- DTG confidence score at session start
    duration_ms  BIGINT                        -- Wall-clock duration in milliseconds
);

-- ─── Indexes ──────────────────────────────────────────────
CREATE INDEX idx_sessions_user_id    ON sessions(user_id);
CREATE INDEX idx_sessions_status     ON sessions(status);
CREATE INDEX idx_sessions_started_at ON sessions(started_at DESC);
CREATE INDEX idx_sessions_metadata   ON sessions USING GIN (metadata);

-- ─── Audit trigger: auto-fill finished_at + duration_ms ──
CREATE OR REPLACE FUNCTION sessions_finish_audit()
RETURNS TRIGGER LANGUAGE plpgsql AS $$
BEGIN
    IF NEW.status IN ('completed','failed','cancelled','timeout')
       AND OLD.status = 'running'
    THEN
        NEW.finished_at := COALESCE(NEW.finished_at, now());
        NEW.duration_ms := EXTRACT(EPOCH FROM (NEW.finished_at - OLD.started_at)) * 1000;
    END IF;
    RETURN NEW;
END;
$$;

CREATE TRIGGER trg_sessions_finish_audit
    BEFORE UPDATE ON sessions
    FOR EACH ROW
    EXECUTE FUNCTION sessions_finish_audit();

-- Record this migration
INSERT INTO schema_migrations (version) VALUES (1)
    ON CONFLICT (version) DO NOTHING;

COMMIT;
