BEGIN;

-- ─── Jobs table ───────────────────────────────────────────
CREATE TABLE jobs (
    id           UUID        PRIMARY KEY DEFAULT uuid_generate_v4(),
    session_id   UUID        NOT NULL REFERENCES sessions(id) ON DELETE CASCADE,
    task_type    TEXT        NOT NULL,
    payload      JSONB       NOT NULL,
    result       JSONB,
    status       TEXT        NOT NULL
                             CHECK (status IN ('queued','running','succeeded','failed','skipped')),
    priority     INT         NOT NULL DEFAULT 0 CHECK (priority BETWEEN 0 AND 10),
    attempt      INT         NOT NULL DEFAULT 0,
    max_attempts INT         NOT NULL DEFAULT 3,
    policy_score DOUBLE PRECISION,
    agent_id     TEXT,                          -- Temporal worker identity
    created_at   TIMESTAMPTZ NOT NULL DEFAULT now(),
    started_at   TIMESTAMPTZ,
    finished_at  TIMESTAMPTZ,
    updated_at   TIMESTAMPTZ NOT NULL DEFAULT now(),
    duration_ms  BIGINT
);

-- ─── Indexes ──────────────────────────────────────────────
CREATE INDEX idx_jobs_session        ON jobs(session_id);
CREATE INDEX idx_jobs_status         ON jobs(status);
CREATE INDEX idx_jobs_task_type      ON jobs(task_type);
CREATE INDEX idx_jobs_created_at     ON jobs(created_at DESC);
CREATE INDEX idx_jobs_priority_queue ON jobs(priority DESC, created_at ASC)
    WHERE status = 'queued';
CREATE INDEX idx_jobs_payload        ON jobs USING GIN (payload);
CREATE INDEX idx_jobs_result         ON jobs USING GIN (result);

-- ─── Auto-update updated_at ───────────────────────────────
CREATE OR REPLACE FUNCTION update_updated_at_column()
RETURNS TRIGGER LANGUAGE plpgsql AS $$
BEGIN
    NEW.updated_at := now();
    RETURN NEW;
END;
$$;

CREATE TRIGGER trg_jobs_updated_at
    BEFORE UPDATE ON jobs
    FOR EACH ROW
    EXECUTE FUNCTION update_updated_at_column();

-- ─── Auto-fill duration on finish ────────────────────────
CREATE OR REPLACE FUNCTION jobs_finish_audit()
RETURNS TRIGGER LANGUAGE plpgsql AS $$
BEGIN
    IF NEW.status IN ('succeeded','failed','skipped')
       AND OLD.status = 'running'
    THEN
        NEW.finished_at := COALESCE(NEW.finished_at, now());
        NEW.duration_ms := EXTRACT(EPOCH FROM (NEW.finished_at - OLD.started_at)) * 1000;
    END IF;
    RETURN NEW;
END;
$$;

CREATE TRIGGER trg_jobs_finish_audit
    BEFORE UPDATE ON jobs
    FOR EACH ROW
    EXECUTE FUNCTION jobs_finish_audit();

-- ─── Useful views ─────────────────────────────────────────

-- Session summary: task counts per session
CREATE VIEW session_summary AS
SELECT
    s.id                                          AS session_id,
    s.status                                      AS session_status,
    s.started_at,
    s.finished_at,
    s.duration_ms,
    COUNT(j.id)                                   AS total_tasks,
    COUNT(j.id) FILTER (WHERE j.status = 'succeeded') AS succeeded_tasks,
    COUNT(j.id) FILTER (WHERE j.status = 'failed')    AS failed_tasks,
    AVG(j.duration_ms)                            AS avg_task_duration_ms
FROM sessions s
LEFT JOIN jobs j ON j.session_id = s.id
GROUP BY s.id;

-- Task failure rate by task_type (last 7 days)
CREATE VIEW task_type_failure_rate AS
SELECT
    task_type,
    COUNT(*)                                           AS total,
    COUNT(*) FILTER (WHERE status = 'failed')          AS failed,
    ROUND(
        COUNT(*) FILTER (WHERE status = 'failed')::numeric
        / NULLIF(COUNT(*), 0) * 100, 2
    )                                                  AS failure_rate_pct,
    AVG(duration_ms)                                   AS avg_duration_ms
FROM jobs
WHERE created_at >= now() - INTERVAL '7 days'
GROUP BY task_type
ORDER BY failure_rate_pct DESC;

