### 1.16 Deployment & Helper Scripts

```bash
#!/usr/bin/env bash
# ═══════════════════════════════════════════════════════════════════════
# init_workspace.sh – Bootstrap GCP project + Kubernetes secrets
# ═══════════════════════════════════════════════════════════════════════
# File: scripts/init_workspace.sh
# Reference: [web:32][web:42]

set -euo pipefail

# ─── Colour output ───────────────────────────────────────────
RED='\033[0;31m'; GREEN='\033[0;32m'; YELLOW='\033[1;33m'; NC='\033[0m'
log_info()  { echo -e "${GREEN}[INFO]${NC}  $*"; }
log_warn()  { echo -e "${YELLOW}[WARN]${NC}  $*"; }
log_error() { echo -e "${RED}[ERROR]${NC} $*" >&2; }

# ─── Required env vars ───────────────────────────────────────
: "${PROJECT_ID:?Please set PROJECT_ID}"
: "${GCP_REGION:=us-central1}"

log_info "════════════════════════════════════════════════════════════"
log_info "AI ENGINEER – WORKSPACE INIT"
log_info "Project: ${PROJECT_ID}  Region: ${GCP_REGION}"
log_info "════════════════════════════════════════════════════════════"

# ─── Step 1: Fetch secrets from Vault or GCP Secret Manager ──
log_info "Fetching secrets..."

if command -v vault &>/dev/null && [[ -n "${VAULT_ADDR:-}" ]]; then
    log_info "Using HashiCorp Vault at ${VAULT_ADDR}"
    OPENAI_API_KEY=$(vault kv get -field=openai_api_key secret/ai-engineer)
    POSTGRES_PASSWORD=$(vault kv get -field=postgres_password secret/ai-engineer)
else
    log_info "Using GCP Secret Manager"
    OPENAI_API_KEY=$(gcloud secrets versions access latest \
        --secret="openai-api-key" --project="${PROJECT_ID}")
    POSTGRES_PASSWORD=$(gcloud secrets versions access latest \
        --secret="postgres-password" --project="${PROJECT_ID}")
fi

export OPENAI_API_KEY POSTGRES_PASSWORD

# ─── Step 2: Configure Docker for Artifact Registry ──────────
log_info "Configuring Docker for Artifact Registry..."
gcloud auth configure-docker "${GCP_REGION}-docker.pkg.dev" --quiet

# ─── Step 3: Build Docker images ─────────────────────────────
log_info "Building base image..."
docker build \
    --platform linux/amd64 \
    --cache-from "${GCP_REGION}-docker.pkg.dev/${PROJECT_ID}/ai-engineer-repo/base:latest" \
    -t "${GCP_REGION}-docker.pkg.dev/${PROJECT_ID}/ai-engineer-repo/base:latest" \
    -f infra/docker/Dockerfile.base .

log_info "Building agent image..."
COMMIT_SHA=$(git rev-parse --short HEAD)
docker build \
    --platform linux/amd64 \
    --build-arg BUILD_DATE="$(date -u +%Y-%m-%dT%H:%M:%SZ)" \
    --build-arg GIT_SHA="${COMMIT_SHA}" \
    --cache-from "${GCP_REGION}-docker.pkg.dev/${PROJECT_ID}/ai-engineer-repo/agent:latest" \
    -t "${GCP_REGION}-docker.pkg.dev/${PROJECT_ID}/ai-engineer-repo/agent:${COMMIT_SHA}" \
    -t "${GCP_REGION}-docker.pkg.dev/${PROJECT_ID}/ai-engineer-repo/agent:latest" \
    -f infra/docker/Dockerfile.agent .

# ─── Step 4: Push to Artifact Registry ───────────────────────
log_info "Pushing images to Artifact Registry..."
docker push "${GCP_REGION}-docker.pkg.dev/${PROJECT_ID}/ai-engineer-repo/base:latest"
docker push "${GCP_REGION}-docker.pkg.dev/${PROJECT_ID}/ai-engineer-repo/agent:${COMMIT_SHA}"
docker push "${GCP_REGION}-docker.pkg.dev/${PROJECT_ID}/ai-engineer-repo/agent:latest"
log_info "Images pushed: agent:${COMMIT_SHA}"

# ─── Step 5: Configure kubectl ───────────────────────────────
log_info "Configuring kubectl..."
gcloud container clusters get-credentials ai-engineer-gke \
    --region "${GCP_REGION}" --project "${PROJECT_ID}"

# ─── Step 6: Create Kubernetes secrets ───────────────────────
log_info "Creating Kubernetes secrets..."

# Compute PostgreSQL DSN
POSTGRES_HOST=$(gcloud sql instances describe ai-engineer-pg-* \
    --format='get(ipAddresses[0].ipAddress)' --project="${PROJECT_ID}" 2>/dev/null \
    || echo "postgres.internal")

POSTGRES_DSN="postgres://ai_user:${POSTGRES_PASSWORD}@${POSTGRES_HOST}:5432/ai_engineer?sslmode=require"

kubectl create secret generic ai-engineer-secrets \
    --namespace ai-engineer \
    --from-literal=openai_api_key="${OPENAI_API_KEY}" \
    --from-literal=postgres_password="${POSTGRES_PASSWORD}" \
    --from-literal=postgres_dsn="${POSTGRES_DSN}" \
    --dry-run=client -o yaml | kubectl apply -f -

# ─── Step 7: Apply Kubernetes manifests ──────────────────────
log_info "Applying Kubernetes manifests..."
for manifest in infra/k8s/*.yaml; do
    log_info "  Applying ${manifest}..."
    # Replace MY_PROJECT placeholder
    sed "s/MY_PROJECT/${PROJECT_ID}/g" "${manifest}" | kubectl apply -f -
done

# ─── Step 8: Wait for rollout ────────────────────────────────
log_info "Waiting for deployments to roll out..."
for deploy in orchestrator planner toolchain testing-agent; do
    kubectl rollout status deployment/"${deploy}" \
        --namespace ai-engineer --timeout=300s
    log_info "  ✓ ${deploy} ready"
done

log_info "════════════════════════════════════════════════════════════"
log_info "WORKSPACE INITIALISATION COMPLETE"
log_info "════════════════════════════════════════════════════════════"
```

